select  from biz_agent

    del_flag = '0'

        and agent_name like concat('%', #{agentName}, '%')


        and category_code = #{categoryCode}


        and publish_status = #{publishStatus}


        and recommend_flag = #{recommendFlag}


order by sort_no asc, agent_id desc

select  from biz_agent

    publish_status = '1' and del_flag = '0'

        and (agent_name like concat('%', #{agentName}, '%') or summary like concat('%', #{agentName}, '%'))


        and category_code = #{categoryCode}


        and recommend_flag = #{recommendFlag}


order by recommend_flag desc, sort_no asc, hot_score desc, published_at desc

