update biz_agent
agent_code = #{agentCode}, agent_name = #{agentName}, category_code = #{categoryCode}, icon_code = #{iconCode}, cover_url = #{coverUrl}, provider_id = #{providerId}, provider_name = #{providerName}, summary = #{summary}, description = #{description}, price_text = #{priceText}, price_min = #{priceMin}, price_max = #{priceMax}, cert_level = #{certLevel}, rating = #{rating}, deploy_count = #{deployCount}, delivery_cycle = #{deliveryCycle}, service_mode = #{serviceMode}, recommend_flag = #{recommendFlag}, hot_score = #{hotScore}, sort_no = #{sortNo}, publish_status = #{publishStatus}, published_at = #{publishedAt}, slug = #{slug}, version_no = version_no + 1, ext_json = #{extJson}, update_by = #{updateBy}, update_time = sysdate(), remark = #{remark}
where agent_id = #{agentId} and del_flag = '0'

